import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"臨","description":"焦氏易林注 - 臨","frontmatter":{"title":"臨","description":"焦氏易林注 - 臨"},"headers":[],"relativePath":"classics/jiaoyilin/019.md","filePath":"classics/jiaoyilin/019.md"}'),l={name:"classics/jiaoyilin/019.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="臨" tabindex="-1">臨 <a class="header-anchor" href="#臨" aria-label="Permalink to “臨”">​</a></h1><h3 id="臨-1" tabindex="-1">臨 <a class="header-anchor" href="#臨-1" aria-label="Permalink to “臨”">​</a></h3><h3 id="臨之乾" tabindex="-1">臨之乾 <a class="header-anchor" href="#臨之乾" aria-label="Permalink to “臨之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>黃獹生子，以戌為母。晉師在郊，虞公出走。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>《初學記》：&quot;獹，韓良犬也&quot;。臨坤為黃，伏艮為獹。震為子，坤為母，候卦居戌，戌狗，故曰以戌為母。震為晉，坤為師、為郊，震為公、為出走、為歡虞。全用遇卦象。○以戌，各本皆作白戌，依《坤》之《震》、《蒙》之《訟》校改。又：生子，依汲古，宋元本作生馬，非。虞滅見僖二年《左傳》。</p><h3 id="臨之坤" tabindex="-1">臨之坤 <a class="header-anchor" href="#臨之坤" aria-label="Permalink to “臨之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>倉唐奉使，中山以孝。文侯悅嘉，擊子徵召。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>詳《豫》之《豐》。此仍用遇卦《臨》象。○倉唐，依宋元本，汲古訛倉皇，擊訛系。</p><h3 id="臨之屯" tabindex="-1">臨之屯 <a class="header-anchor" href="#臨之屯" aria-label="Permalink to “臨之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>機關不便，不能出言。精誠不通，為人所冤。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>坎為機關，坎陷故不便。坤閉故不能出言。震為言、為出、為精、為通、為人，坤閉故不通。坎為冤。</p><h3 id="臨之蒙" tabindex="-1">臨之蒙 <a class="header-anchor" href="#臨之蒙" aria-label="Permalink to “臨之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>白茅醴酒，靈巫拜禱。神嗜飲食，使君壽考。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《坎》。</p><h3 id="臨之需" tabindex="-1">臨之需 <a class="header-anchor" href="#臨之需" aria-label="Permalink to “臨之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>重瞳四乳，耳聰目明。普仁表聖，為作元輔。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>《淮南子》：&quot;舜重瞳，文四乳&quot;。《需》通《晉》。坤為重，離為目，故曰重瞳。艮為乳，兌納丁，數四故曰四乳。坎為耳，離為目、為聰明，乾為仁聖、為元。○三四句依汲古，宋元本作&quot;普為仁表，聖作元輔&quot;。</p><h3 id="臨之訟" tabindex="-1">臨之訟 <a class="header-anchor" href="#臨之訟" aria-label="Permalink to “臨之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>水長無船，破城壞堤。大夫從役，一朝亡殞，不見少妻。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>通《明夷》。坎為水，坤水，震為長、為船，坎伏故無船。艮為城、為堤，艮覆故壞。震為夫，坤為役，故大夫從役。震為朝，坎數一，故曰一朝。巽為少妻，坤亡故不見。○長，依宋元本，汲古作漲。宋元本從役下多&quot;困於泥塗&quot;四字。</p><h3 id="臨之師" tabindex="-1">臨之師 <a class="header-anchor" href="#臨之師" aria-label="Permalink to “臨之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>二人俱行，各遺其囊。鴻鵠失珠，無以為明。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>震為人，坤數二，故曰二人。坤為囊、為亡，故各遺其囊。震為鴻鵠、為珠，坤為失，故曰失珠。離為明，離伏無無明。他林屢有鶴盜我珠、鵠怒追求等繇辭，然則鴻鵠失珠必有故實，今不能考。○二人，依宋元本，汲古作六。</p><h3 id="臨之比" tabindex="-1">臨之比 <a class="header-anchor" href="#臨之比" aria-label="Permalink to “臨之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>隨時轉行，不失其常。鹹樂厥類，身無咎殃。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮為時，坤為身、為咎殃，鹹樂厥類者，言九五與群陰為類而樂也。○鹹樂，依宋本，汲古作各樂，非。</p><h3 id="臨之小畜" tabindex="-1">臨之小畜 <a class="header-anchor" href="#臨之小畜" aria-label="Permalink to “臨之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>蔡女蕩舟，為國患憂。褒後在側，屏蔽王目，搔擾六國。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>《左傳僖二年》：&quot;齊侯與蔡姬乘舟於囿，盪公，公懼變色，怒歸之，未絕之也，蔡人嫁之，明年侵蔡&quot;，褒後，幽王后。巽為蔡、為女，伏震為舟，坤為國、為憂患、為後，乾為王，伏坎為屏蔽，離為目。○搔擾六國，依宋元本，汲古作早衰六畜，非。</p><h3 id="臨之履" tabindex="-1">臨之履 <a class="header-anchor" href="#臨之履" aria-label="Permalink to “臨之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>駕龍騎虎，周遍天下。為神人使，西見王母，不憂危殆。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>伏《謙》。震為龍，艮為虎，故曰駕龍騎虎。震為周，坤為天下。震為神、為人、為行，故曰為神人使。坎位西，震為王，坤母，故曰王母。坎憂震樂，故不憂。○為神人使，依汲古，宋本作為人所使。危殆，元本作不殆，依汲古。此用穆王西巡狩事。</p><h3 id="臨之泰" tabindex="-1">臨之泰 <a class="header-anchor" href="#臨之泰" aria-label="Permalink to “臨之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>員怨之吳，畫策闔閭。鞭平服荊，除大咎殃。威振敵國，還受上卿。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>伍子胥名員，平王既殺其父兄，員犇吳，佐吳王闔閭伐楚，鞭平王之屍。震為員，員，雲也。震為行、為南，故之吳。伏艮為手、為畫、為閭，伏巽為鞭、為荊，坤為殃咎，在外故曰除。坤為國，震為威、為公，故曰上卿。○員怨，從宋本，汲古作胥恐。閭廬通。</p><h3 id="臨之否" tabindex="-1">臨之否 <a class="header-anchor" href="#臨之否" aria-label="Permalink to “臨之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>唐邑之墟，晉人以居。虞叔受福，實沈是國，世載其樂。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>坤為邑、為墟，伏震為唐。《玉篇》堯稱唐者，至大之貌，乾大，故曰唐邑之墟。《說文》：&quot;唐，大言也&quot;，《莊子天下篇》荒唐之言是也。震為晉、為人，艮為居，故曰晉人以居。艮為叔，乾為福，實沈，星次晉分。《左傳》&quot;參為晉星&quot;，實沈，參神也。艮為星，坤國故曰實沈是國。坤為世、為載，伏震為樂。《史記晉世家》：&quot;唐叔虞者，成王弟，封於唐，至子爕徙居晉水，是為晉侯&quot;。 ○墟，依宋本，汲古作廬，非。以，依汲古，宋本作之。</p><h3 id="臨之同人" tabindex="-1">臨之同人 <a class="header-anchor" href="#臨之同人" aria-label="Permalink to “臨之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>管鮑相知，至德不離。三言相桓，齊國以安。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>《史記》：&quot;管仲少與鮑叔牙遊，鮑叔知其賢，薦於桓公，管子曰：&quot;倉廩實而知禮節，衣食足而知榮辱，上服度則六親固&quot;，三言蓋指此。《韓詩外傳》&quot;君子有三言可貫而佩之&quot;是也。《同人》通《師》。震為管，坤為魚、為鮑，震為言、為桓，數三故曰三言。坤為國、為安。巽為齊。○相桓，依宋元本，汲古作於，非。</p><h3 id="臨之大有" tabindex="-1">臨之大有 <a class="header-anchor" href="#臨之大有" aria-label="Permalink to “臨之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>三十無室，長女獨宿。心勞未得，憂在胸臆。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>離卦數三，兌數十，坎為室，坎伏故曰三十無室。兌為老婦，故為長女。坎為宿、為孤，故曰獨宿。坎為心、為勞、為憂，伏坤為胸臆。按：《大過九五》雲老婦指兌也。</p><h3 id="臨之謙" tabindex="-1">臨之謙 <a class="header-anchor" href="#臨之謙" aria-label="Permalink to “臨之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>散渙水長，風吹我鄉。火滅無光，隳敗桓公。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>坎水坤水故曰水長，伏巽風故曰散渙、曰風吹。坤為我、為鄉，艮為火、為光，上臨坎水坤水，故火滅無光。震為桓、為公，坤喪故曰隳敗，言桓公死，齊亂如火滅也。</p><h3 id="臨之豫" tabindex="-1">臨之豫 <a class="header-anchor" href="#臨之豫" aria-label="Permalink to “臨之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>蜎飛蠕動，各有配偶。小大相保，鹹得其所。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>蜎、蠕，皆蟲行貌，伏巽為蟲，故曰蜎飛蠕動。巽震為夫婦，故曰各有配偶。坤為小，伏乾為大，艮止故曰相保。○蜎飛，從汲古，宋元本作飛蜎，《詩》&quot;蜎蜎者蠋&quot;。</p><h3 id="臨之隨" tabindex="-1">臨之隨 <a class="header-anchor" href="#臨之隨" aria-label="Permalink to “臨之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>安樂幾筵，未出王門。艮安震樂。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>艮幾震筵，震為王，艮為門，艮止故未出。</p><h3 id="臨之蠱" tabindex="-1">臨之蠱 <a class="header-anchor" href="#臨之蠱" aria-label="Permalink to “臨之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>火生月窟，下土恩塞，抵亂我國。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>巽先天位西南，為月窟，兌為月，艮為火，故曰火生月窟。下互大坎，坎為土、為塞，兌為恩澤、為羊，故曰抵。艮為國，兌毀，故曰抵亂我國。○艮為火、巽為西南、坎為土之確證。</p><h3 id="臨之臨" tabindex="-1">臨之臨 <a class="header-anchor" href="#臨之臨" aria-label="Permalink to “臨之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>弱水之西，有西王母。生不知老，與天相保。行者危殆，利居善喜。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>坤為水，坤柔，故曰弱水。坤為母，震為王，兌西，故曰有西王母。震為生，坤為老，震樂而健，故不知老。伏乾為天，艮為保，震為行，坤喪故危殆、故不行，而居則利也。伏艮為居。○之西，依汲古，宋元本作之上。</p><h3 id="臨之觀" tabindex="-1">臨之觀 <a class="header-anchor" href="#臨之觀" aria-label="Permalink to “臨之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>長生無極，子孫千億。柏柱載梁，堅國不傾。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>巽為長，伏震為生、為子，艮為孫，坤為千億，巽為柏、為樑柱，艮為堅固，巽為傾。○梁，從汲古，元本作青，非。</p><h3 id="臨之噬嗑" tabindex="-1">臨之噬嗑 <a class="header-anchor" href="#臨之噬嗑" aria-label="Permalink to “臨之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>欽敬昊天，厯象星辰。宣授民時，陰陽和調。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>離為夏，故曰昊天。艮為星辰、為時，坎為眾、為民，離坎為夫婦，故曰陰陽和調。○宣，從宋本，汲古作宜，非。</p><h3 id="臨之賁" tabindex="-1">臨之賁 <a class="header-anchor" href="#臨之賁" aria-label="Permalink to “臨之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>三河俱合，水怒踴躍。壞我王屋，民困於食。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>坎為河，震數三，故曰三河。坎為合、為水，震為怒、為踴躍、為王，艮為屋，伏巽為壞。坎為民，兌為食，又：河東、河南、河內亦曰三河。○屋，汲古作室，依宋本。</p><h3 id="臨之剝" tabindex="-1">臨之剝 <a class="header-anchor" href="#臨之剝" aria-label="Permalink to “臨之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>壽如松喬，與日月俱。常安康樂，不離禍憂。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為壽、為木、為仙，故曰松喬。赤鬆、王喬，古之仙人。與日月俱，言壽永也。伏兌為月，艮為日。兌為悅，故曰康樂。坤為禍憂，一陽在上故不罹禍憂。○離，同罹，依汲古，宋本作不見，非。</p><h3 id="臨之復" tabindex="-1">臨之復 <a class="header-anchor" href="#臨之復" aria-label="Permalink to “臨之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>天之所與，福祿常在，不憂危殆。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>伏乾為天、為福祿，坤為憂、為殆，震樂故不憂。</p><h3 id="臨之無妄" tabindex="-1">臨之無妄 <a class="header-anchor" href="#臨之無妄" aria-label="Permalink to “臨之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>受讖六符，招搖室虛。雖跌無憂，保我命財。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>讖，《說文》驗也。《漢書東方朔傳》&quot;願陳泰階六符&quot;，《藝文志》泰階六符一捲，李奇註：三臺謂之泰階，兩兩成體，三合故六觀，色以知吉凶，故曰六符。招搖室虛，皆星宿名。乾數六，艮為星，巽為跌，震樂故無憂。巽為命，乾為財，互艮為安，故命與資財可保也。○室，依汲古，宋本訛空，六符，三臺星名。三臺共六星，故曰六符。雖跌無憂者，艮為星，艮覆為震，故無憂。又末二字汲古作命則，宋元本作全財，茲命字依汲古，財依宋元本。</p><h3 id="臨之大畜" tabindex="-1">臨之大畜 <a class="header-anchor" href="#臨之大畜" aria-label="Permalink to “臨之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>齎金賈車，失道後時，勞罷為憂。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>乾為金，艮手為齎，震為車、為後，艮為道、為時，在外故失道後時。伏大坎為勞、為憂。○宋元本多&quot;我心則休&quot;四字，汲古無。</p><h3 id="臨之頤" tabindex="-1">臨之頤 <a class="header-anchor" href="#臨之頤" aria-label="Permalink to “臨之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>華首山頭，仙道所遊。利以居止，長無咎憂。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>艮為山、為首，伏兌為華，艮為壽、為仙道、為居止。坤為憂，震樂故無憂。○利以，依宋元本，汲古作利於。咎憂，依汲古，宋元本作憂咎。華、首，皆山名。</p><h3 id="臨之大過" tabindex="-1">臨之大過 <a class="header-anchor" href="#臨之大過" aria-label="Permalink to “臨之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>採唐沬鄉，要期桑中。失信不會，憂思約帶。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《噬嗑》。《詩》&quot;我心蘊結&quot;，又曰&quot;心如結兮&quot;，即約帶之義。楊慎謂即衣帶日以緩之意，非。</p><h3 id="臨之坎" tabindex="-1">臨之坎 <a class="header-anchor" href="#臨之坎" aria-label="Permalink to “臨之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>人面鬼口，長舌為斧。斫破瑚璉，殷商絕後。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《謙》。○人面，依汲古，宋元本作八面，非。鬼，各本皆作九，依《否》之《謙》校改，實鬼與九皆通用，紂臣鬼侯亦作九侯是其證。</p><h3 id="臨之離" tabindex="-1">臨之離 <a class="header-anchor" href="#臨之離" aria-label="Permalink to “臨之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>臨溪橋疚，雖恐不危，樂以笑歌。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>兌為溪，伏艮為橋，伏坎為恐、為危，震為樂、為笑歌。○橋疚，宋元本作蟠枝，汲古作橋疚。疚，疑為仄，故雖恐不危。蟠當為播，播，種也。播枝，言種樹也。</p><h3 id="臨之鹹" tabindex="-1">臨之鹹 <a class="header-anchor" href="#臨之鹹" aria-label="Permalink to “臨之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>洋洋沸溢，水泉為害，使我無賴。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>互大坎故曰洋溢、曰水泉為害，兌毀為害。伏坤為我。</p><h3 id="臨之恆" tabindex="-1">臨之恆 <a class="header-anchor" href="#臨之恆" aria-label="Permalink to “臨之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>蝗螟為賊，害我稼穡。秋飢於年，農夫鮮食。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>巽為蝗蟲、為稼穡，巽為賊、為害，兌毀亦為害。兌為秋，乾為年，伏坤為飢。震為農夫，兌為食，兌毀巽落故鮮食。○害我、秋飢，依汲古，宋本作傷害、作愁飢。</p><h3 id="臨之遯" tabindex="-1">臨之遯 <a class="header-anchor" href="#臨之遯" aria-label="Permalink to “臨之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>八百諸侯，不期同時。慕西文德，興我宗族，家門雍睦。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>巽為辛，數八，艮後天數亦八，乾為百，伏震為諸侯，故曰八百諸侯。艮為時，伏兌為西，坤為文、為門、為族，乾為宗，艮為家。○雍睦，依汲古，宋本作雍雍。八，汲古訛六，族訛旅，依宋元本。《史記》：&quot;武王觀兵孟津，諸侯不期而會者八百&quot;。</p><h3 id="臨之大壯" tabindex="-1">臨之大壯 <a class="header-anchor" href="#臨之大壯" aria-label="Permalink to “臨之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>長男少女，相向笑語。來歡致福，和悅樂喜。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>震為長男，兌為少女，震為笑語、為歡、為和樂、為喜。乾為福。</p><h3 id="臨之晉" tabindex="-1">臨之晉 <a class="header-anchor" href="#臨之晉" aria-label="Permalink to “臨之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>平國不君，夏氏作亂。烏號竊發，靈公殞命。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>坤為國，坎為平，震為君，震覆故不君。平國，陳靈公名。離為夏、為亂，夏氏，徵舒也。離為烏，坎為弓、為竊。烏號，弓名。坤為殞，言徵舒恥靈公與其母夏姬亂，射殺靈公也。事在《左傳宣十年》。</p><h3 id="臨之明夷" tabindex="-1">臨之明夷 <a class="header-anchor" href="#臨之明夷" aria-label="Permalink to “臨之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>春多膏澤，夏潤優渥。稼穡成熟，畝獲百斛。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為春，坎為膏澤，離為夏，坎為潤渥。震為稼穡，離火故曰熟。坤為畝、為百，震為斛。○成熟，依汲古，元本作熟成。</p><h3 id="臨之家人" tabindex="-1">臨之家人 <a class="header-anchor" href="#臨之家人" aria-label="Permalink to “臨之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>客宿臥寒，席蓐不安。行危為害，留止得歡。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>此用《臨》象。震為客，坤為宿，伏乾為寒，巽為伏，故曰臥寒。巽為蓐、為進退，故不安。○行危為害，留止得歡。汲古作&quot;行為危害，留不得歡&quot;，依宋元本。《左傳》不行之謂臨，故三四句云云。</p><h3 id="臨之睽" tabindex="-1">臨之睽 <a class="header-anchor" href="#臨之睽" aria-label="Permalink to “臨之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>乘桴浮海，雖懼不殆。母載其子，終焉何咎。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>此用《臨》象。臨震為桴、為乘，坤水兌澤，故曰海。坤為懼、為母，震為子，故母載其子。伏艮為終。○桴，依宋本，汲古作槎。浮，依宋本，汲古作於。桴，編竹木代舟也，大曰筏，小曰桴。《論語》乘桴浮於海。</p><h3 id="臨之蹇" tabindex="-1">臨之蹇 <a class="header-anchor" href="#臨之蹇" aria-label="Permalink to “臨之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>手拙不便，不能伐檀。車無軸轅，行者苦難。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>艮為手，坎陷故不便。艮為伐、為檀。檀，堅木也。艮止故不能。坎為車，多眚，故無軸轅。震為行，震反為艮，故難行。《詩》&quot;檀車煌煌&quot;，古嘗以檀造車，今不能伐檀，故無軸轅。</p><h3 id="臨之解" tabindex="-1">臨之解 <a class="header-anchor" href="#臨之解" aria-label="Permalink to “臨之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>唐虞相輔，鳥獸率舞。民安無事，國家富有。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>震為帝，故曰唐虞，為鳥、為舞，坎為眾、為民，《臨》坤為國家、為富有。</p><h3 id="臨之損" tabindex="-1">臨之損 <a class="header-anchor" href="#臨之損" aria-label="Permalink to “臨之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>秋蛇向穴，不失其節。夫人薑氏，自齊復入。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>兌為秋，坤為蛇，艮為穴，震為夫、為人，伏巽為薑、為齊、為入。</p><h3 id="臨之益" tabindex="-1">臨之益 <a class="header-anchor" href="#臨之益" aria-label="Permalink to “臨之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>病篤難醫，和不能治。命終永訖，下即蒿廬。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>伏《恆》。坎為病，互大坎，故曰病篤。坎為和，坤死，故曰難醫、曰和不能治、曰命終永訖。巽為命，艮為終，巽為蒿，艮為盧，故曰蒿盧。蒿盧，即蒿里。《左傳》：&quot;晉景公疾，秦伯使醫緩為之，緩曰：是在肓之上、膏之下，攻之不可，達之不及，無能為也，既而公果卒&quot;。 ○永訖，依汲古，元本作斯訖。</p><h3 id="臨之夬" tabindex="-1">臨之夬 <a class="header-anchor" href="#臨之夬" aria-label="Permalink to “臨之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>青蛉如雲，城邑閉門。國君衛守，民困於患。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>青蛉，即蜻蛉。《漢志》&quot;越巂有青蛉縣&quot;，《水經註》引作蜻蛉，《埤雅》蜻蜓一名蜻蛉，《呂氏春秋》&quot;海上有人好蜻蛉，每至海上，蜻蛉從遊者數萬&quot;。《夬》通《剝》。坤為雲、為城邑、為閉、為國、為民、為患，艮為守，蜻蛉大首薄翼。艮一陽在上，疑即《剝》艮象也。○閉，依元本，汲古本、宋本作關。</p><h3 id="臨之姤" tabindex="-1">臨之姤 <a class="header-anchor" href="#臨之姤" aria-label="Permalink to “臨之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>牙櫱生達，室堂啟戶。出入利貞，鼓翼起舞。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>此亦全用《臨》象。震為牙櫱、為生，坤為堂戶，震為出，巽入，故曰出入利貞。震為鼓、為翼、為起舞。○出入，依汲古，宋元本作幽人。貞，依宋元本，汲古訛真。首句各本作牙孽生齒，依《小畜》之《睽》校。</p><h3 id="臨之萃" tabindex="-1">臨之萃 <a class="header-anchor" href="#臨之萃" aria-label="Permalink to “臨之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>鳧遊江海，沒行千里。以為死亡，復見空桑，長生樂鄉。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>艮為鳧，坤為江海、為千里。坤為死亡，巽為桑，坤虛，故曰空桑。伏震為生，兌悅故曰樂鄉。坤為鄉。林意謂鳧沒江海，不見以為死亡矣，後復見於空桑，不惟未死，且甚安樂也。○海沒，依宋元本，汲古作湖役。</p><h3 id="臨之升" tabindex="-1">臨之升 <a class="header-anchor" href="#臨之升" aria-label="Permalink to “臨之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>黃帝出遊，駕龍乘馬。東上泰山，南遊齊魯，邦國鹹喜。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>震為黃、為帝、為遊、為龍、為馬、為東，伏艮為山，故東上泰山。震又為南，巽齊兌魯，故南遊齊魯。坤為邦國，震為喜。○馬，依宋本，汲古作鳳，非。</p><h3 id="臨之困" tabindex="-1">臨之困 <a class="header-anchor" href="#臨之困" aria-label="Permalink to “臨之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>履危不止，與鬼相視。驚恐失氣，如騎虎尾。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>通《賁》。坎為危，在震下，故曰履危。坎為鬼，離為視，離坎連體，故曰相視。震為驚、為騎，艮為虎尾，謂遇鬼驚恐如履虎尾也。</p><h3 id="臨之井" tabindex="-1">臨之井 <a class="header-anchor" href="#臨之井" aria-label="Permalink to “臨之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>秋南春北，不失消息。涉和履中，時無隱匿。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>通《噬嗑》。兌秋離南，震春坎北，雁秋南鄉，春北歸，故不失消息。又消息卦起坎離，亦不失也。坎為和、為中，震為涉、為履，艮為時，坎為隱匿，四時畢見，故無隱匿。○隱，汲古作陰，依元本。</p><h3 id="臨之革" tabindex="-1">臨之革 <a class="header-anchor" href="#臨之革" aria-label="Permalink to “臨之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>龍門砥柱，通利水道。百川順流，民安其居。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。震為龍，艮為門、為柱、為石，故曰龍門砥柱。震為通，巽為利，坎水艮道。《禹貢》：&quot;道河積石，至於龍門，東至砥柱&quot;是也。震為百，坎為川、為流、為民，艮為安、為居，故曰民安其居。</p><h3 id="臨之鼎" tabindex="-1">臨之鼎 <a class="header-anchor" href="#臨之鼎" aria-label="Permalink to “臨之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>千歲廟堂，棟橈傾僵。天厭周德，失其寵光。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。坤為千歲，艮為廟堂。巽為棟、為隕落，故曰橈、曰傾僵。震為周，艮為天、為光，坎失，故曰失其寵光。○橈，依宋本，汲古本作撓，非。</p><h3 id="臨之震" tabindex="-1">臨之震 <a class="header-anchor" href="#臨之震" aria-label="Permalink to “臨之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>折若蔽目，不見稚叔。三足孤鳥，遠離室家。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>坎為折，震為若。若木也。離為目，離伏坎隱，故曰蔽目、曰不見稚叔。艮為叔、為少男，故曰稚叔。震為足，數三，艮為烏，坎孤，故曰三足孤烏。艮為室家。</p><h3 id="臨之艮" tabindex="-1">臨之艮 <a class="header-anchor" href="#臨之艮" aria-label="Permalink to “臨之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>望叔山北，陵隔我目。不見所得，使我心惑。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>艮為望、為叔，互坎為北，故曰山北。坎為隱，離伏，故曰陵隔我目、曰不見所得。坎為心、為憂，故曰心惑。○心，依汲古，元本作憂。</p><h3 id="臨之漸" tabindex="-1">臨之漸 <a class="header-anchor" href="#臨之漸" aria-label="Permalink to “臨之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>匏瓠之息，一畝千室。萬國都邑，北門有福。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>艮為果、為匏瓠。息者，生也，子也。艮為室。《說文》：&quot;室，實也&quot;，言匏瓠之實一畝得千也。伏震為千，坎數一，故曰一畝千室。艮為國、為都邑、為門，坎北，故曰北門。○息，依汲古，宋元本作恩，非。千，依宋元本，汲古訛十。</p><h3 id="臨之歸妹" tabindex="-1">臨之歸妹 <a class="header-anchor" href="#臨之歸妹" aria-label="Permalink to “臨之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>域域牧牧，憂禍相伴。隔以巖山，室家分散。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>通《漸》。坎為憂，離為禍，坎離連體，故曰相伴。艮為山、為室家，艮止，故曰隔。伏巽故曰分散。○以，依宋元本，汲古作我。</p><h3 id="臨之豐" tabindex="-1">臨之豐 <a class="header-anchor" href="#臨之豐" aria-label="Permalink to “臨之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>騏驥騄耳，遊食萍草。逍遙石門，循山上下，不失其所。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>通《渙》。震為馬，故曰騏驥騄耳。震為食、為草，草在坎水上，故曰萍草。震為逍遙、為食，艮為門、為山，中爻正反震艮，故曰循山上下。○所，依宋本，汲古作子。</p><h3 id="臨之旅" tabindex="-1">臨之旅 <a class="header-anchor" href="#臨之旅" aria-label="Permalink to “臨之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>天所祚昌，文以為良。篤生武王，姬受其福。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>艮為天，伏震為祚、為昌。離為文，伏震為生、為武、為王、為姬、為福。</p><h3 id="臨之巽" tabindex="-1">臨之巽 <a class="header-anchor" href="#臨之巽" aria-label="Permalink to “臨之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>羊腸九榮，相推稍前。止須王孫，乃能上天。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>詳《蠱》之《剝》。此皆用伏震象，以互艮為天。</p><h3 id="臨之兌" tabindex="-1">臨之兌 <a class="header-anchor" href="#臨之兌" aria-label="Permalink to “臨之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>貧鬼守門，日破我盆。孤牝不駒，雞不成雛。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》。互坎為鬼，艮為守、為門，震為盆，坎為破。兌為牝，震為駒，震伏，故不駒。巽為雞，艮為雛，艮伏，故不雛。</p><h3 id="臨之渙" tabindex="-1">臨之渙 <a class="header-anchor" href="#臨之渙" aria-label="Permalink to “臨之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>飽食從容，入門上堂。不失其常，家無咎殃。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>坎為飲食，震樂故從容。艮為門、為堂，巽為入，艮為家，坎為殃，震解故無。○入門，依汲古，宋元本作出門，非。</p><h3 id="臨之節" tabindex="-1">臨之節 <a class="header-anchor" href="#臨之節" aria-label="Permalink to “臨之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>陰淫不止，白馬為海。皋澤之子，就高而處。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>坎為水，故曰陰淫。震為白、為馬，兌為海。白馬，津名，在大伾山南，言水多，津變為海也。震為子，艮為皋，兌為澤，言皋澤之人，因水多皆就高而處也。○海，依汲古，宋元本作洶。皋澤，依宋元本，汲古作澤皋，非。皋澤，猶山澤也。</p><h3 id="臨之中孚" tabindex="-1">臨之中孚 <a class="header-anchor" href="#臨之中孚" aria-label="Permalink to “臨之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>執戈俱立，以備暴急。千人守門，因以益卑，終安何畏。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>艮為戈、為執，震為立、為暴急、為千人，艮為守、為門，兌為澤、為下，故曰卑。艮為終、為安，震樂故無畏。○守門、因以益卑，依宋元本，汲古作舉龍、作困危得海。</p><h3 id="臨之小過" tabindex="-1">臨之小過 <a class="header-anchor" href="#臨之小過" aria-label="Permalink to “臨之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>夾河為婚，水長無船。槌心失望，不見所歡。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>互大坎故曰夾河、曰水長。震為船，兌毀故無。艮為槌，坎為心，艮為望，坎失故曰失望。震為歡。○水長，依宋元本，汲古作漲。槌心，依釋文，汲古作追，元本作遙，皆非。</p><h3 id="臨之既濟" tabindex="-1">臨之既濟 <a class="header-anchor" href="#臨之既濟" aria-label="Permalink to “臨之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>陰陽變化，各得其宜。上下順通，奏為膚功。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>言陰陽六爻各當位。</p><h3 id="臨之未濟" tabindex="-1">臨之未濟 <a class="header-anchor" href="#臨之未濟" aria-label="Permalink to “臨之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>任劣德薄，失其臣妾。田不見禽，犬無所得。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>臣妾與犬，皆用《臨》伏象艮。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
